import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"Fast-WAM: Do World Action Models Need Test-time Future Imagination?","description":"","frontmatter":{"title":"Fast-WAM: Do World Action Models Need Test-time Future Imagination?","arxiv":"2603.16666","date":"2026-03-17","authors":"Tianyuan Yuan, Zibin Dong, Yicheng Liu, Hang Zhao","categories":"cs.CV, cs.AI","topics":"通用具身智能, 世界动作模型, 视频协同训练","outline":[2,2]},"headers":[],"relativePath":"papers/2603.16666.md","filePath":"papers/2603.16666.md","lastUpdated":null}'),l={name:"papers/2603.16666.md"};function e(m,s,i,r,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="fast-wam-do-world-action-models-need-test-time-future-imagination" tabindex="-1">Fast-WAM: Do World Action Models Need Test-time Future Imagination? <a class="header-anchor" href="#fast-wam-do-world-action-models-need-test-time-future-imagination" aria-label="Permalink to &quot;Fast-WAM: Do World Action Models Need Test-time Future Imagination?&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2603.16666" target="_blank" rel="noreferrer">2603.16666</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-03-17</td></tr><tr><td><strong>作者</strong></td><td>Tianyuan Yuan, Zibin Dong, Yicheng Liu, Hang Zhao（清华 IIIS / Galaxea AI）</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>把「训练时做视频预测」和「推理时生成未来」拆成两个可单独开关的变量做对照实验，结论是前者值 8 分而后者值不到 1 分，于是干脆在推理期丢掉视频分支，190 ms 出一个动作块。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>本文基于 arXiv v2（2026-03-23 修订）撰写，abs 页的 HTML 入口即指向 v2；v1 提交于 2026-03-17。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>World Action Model（WAM）这一类方法的标准做法是 imagine-then-execute：先用视频扩散模型把未来若干帧生成出来，再从生成的未来里解出动作。这个流程有一个直接的工程代价——推理时要跑完整的迭代去噪，延迟从几十毫秒涨到接近一秒，闭环控制频率被压到个位数赫兹。</p><p>但比延迟更值得追问的是归因问题。WAM 相对普通 VLA 的增益可能来自两个完全不同的地方：一是训练阶段的视频预测目标塑造了骨干的表示，二是推理阶段真的「看到」了一段未来从而获得了前瞻信息。现有系统把这两件事绑死在一起——同一个模型既用视频损失训练、又在部署时生成视频，所以没人知道哪一半在起作用。如果起作用的是前者，那整个 imagine-then-execute 的推理开销就是白付的。</p><p>这个问题值得解决，因为它直接决定了 WAM 的工程形态：如果未来想象在推理期可省，那 WAM 就退化成「带视频辅助损失的 VLA」，可以按 VLA 的延迟预算部署；如果不可省，那所有加速工作都必须围绕视频去噪展开。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>VLA 路线（OpenVLA、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>）把大规模视觉-语言骨干直接映射到动作，语义泛化强，但预训练主要建立在静态图文数据上，不显式建模世界如何随动作演化。WAM 路线正是针对这一点：Motus、LingBot-VA 这类方法把视频与动作在共享注意力下联合建模，报告了明显优于 VLA 的成绩。</p><p>问题在于这些工作的对照都不干净。Motus 与 LingBot-VA 都同时引入了三样东西——视频预训练骨干、视频协同训练目标、推理期未来生成，而消融通常只做「有没有视频分支」这一层，得到的结论必然是「视频有用」，却无法区分是训练期有用还是推理期有用。VPP 与 UVA 已经部分触及这一点：VPP 用视频扩散模型的单步预测特征作为策略条件、UVA 在推理时跳过视频解码，两者都说明「不完整生成未来」也能工作；但它们各自只给出一个可行点，没有在同一框架下把两个因素分别开关，因此仍不构成对「未来想象是否必要」的判决性证据。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>已有的经验观察有两条。第一条来自 VPP 与 UVA：不解码完整视频、只取视频模型的中间表示，下游控制不掉分。第二条来自表示学习的常识：辅助生成目标常常主要通过塑造中间表示起作用，输出本身未必需要被使用。把两条放在一起，一个自然的怀疑是——WAM 的视频分支可能扮演的是 auxiliary loss 的角色，而不是 planner 的角色。</p><p>要验证这个怀疑，需要的不是再提一个更快的 WAM，而是一个能把两个因素正交拆开的实验矩阵。于是设计就被反推出来了：搭一个骨干，让它在训练期一定带视频损失、在推理期可以选择生成或不生成未来；再复刻两种主流的 imagine-then-execute 结构（联合去噪、先视频后动作）作为「推理期生成」的两个代表点；最后加一个「训练期也不带视频损失」的变体作为空对照。三档配置，两个自变量，读表即可归因。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>视频预测目标的价值可能不在于它产出的那段视频，而在于它逼迫骨干把深度、运动连续性、接触结构编码进中间特征。既然动作头读的是中间特征而不是像素，那么把这段特征拿来直接回归动作，和先把它渲染成像素、再从像素里解回运动，理论上携带的信息量是一样的——后者只是多绕了一圈，还多付了几十步去噪。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>骨干是 Wan2.2-5B 的视频 DiT，复用其 T5 文本编码器与视频 VAE；在其旁边挂一个隐藏维 1024 的 action expert DiT（约 1B），两者组成共享注意力的 Mixture-of-Transformer，总计约 6B 参数。动作块长度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">h</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">32</span></span></span></span>，视频侧时间下采样 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">4</span><span class="mord">×</span></span></span></span> 得到每块 9 帧，多相机图像在进 VAE 前先拼成一张大图。</p><p>以一个折毛巾任务为例，完整流程是：</p><ul><li><strong>输入</strong>：当前多相机观测拼成的一帧图像、语言指令。</li><li><strong>token 组织</strong>：三组 token——首帧观测的干净 latent（共享视觉锚点）、未来帧的带噪 latent（仅训练期存在）、动作 token。三组都通过 cross-attention 读语言。</li><li><strong>注意力掩码</strong>：未来视频 token 在视频分支内双向注意并可读干净首帧；动作 token 在动作分支内双向注意并可读干净首帧；<strong>动作 token 不允许读未来视频 token</strong>，干净首帧 token 不读任何其他 token。这条掩码是全文的关键——它保证动作分支拿到的只有 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="mopen">(</span><span class="mord mathnormal">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mclose">)</span></span></span></span>，未来信息不会泄漏。</li><li><strong>训练</strong>：视频与动作共用 flow matching。对目标 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span></span></span></span> 采噪声 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">ϵ</span></span></span></span> 与时间 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span>，构造 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mord mathnormal">ϵ</span></span></span></span>，回归速度场 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">FM</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathbb">E</span><span class="mord">∥</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">t</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">ϵ</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mclose">)</span><span class="mord"><span class="mord">∥</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-2.4519em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2481em;"><span></span></span></span></span></span></span></span></span></span>，总损失 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">act</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord mathnormal">λ</span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">vid</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>。</li><li><strong>推理</strong>：整条未来视频分支被删除，只把干净首帧 latent 过一次视频 DiT 得到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="mopen">(</span><span class="mord mathnormal">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mclose">)</span></span></span></span>，动作 expert 在其上做 10 步去噪（CFG 尺度 1.0）产出 32 步动作块。实测单卡 RTX 5090D 上 190 ms。</li></ul><p>三个对照变体：Fast-WAM-Joint（视频与动作 token 联合去噪）、Fast-WAM-IDM（先生成未来视频，再据此预测动作，对真值视频以 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.5</span></span></span></span> 加噪增强）、Fast-WAM w/o video co-train（架构与推理不变，只去掉视频损失）。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>标准 WAM 的 imagine-then-execute 写成对未来观测的边缘化：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight" style="margin-right:0.0813em;">H</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.2222em;vertical-align:-0.8622em;"></span><span class="mop op-symbol large-op" style="margin-right:0.4445em;position:relative;top:-0.0011em;">∫</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight" style="margin-right:0.0813em;">H</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">d</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord">.</span></span></span></span></span></p><p>Fast-WAM 直接把动作分布参数化为潜世界表示的函数：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight" style="margin-right:0.0813em;">H</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:-0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;">(</span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight" style="margin-right:0.0813em;">H</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="mopen">(</span><span class="mord mathnormal">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mclose">)</span><span class="mclose delimcenter" style="top:0em;">)</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="mopen">(</span><span class="mord mathnormal">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mclose">)</span></span></span></span> 由一次前向编码得到，而非采样或去噪 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>。</p><p>这里有一个值得点破的信息论事实（论文未显式论证，属基于公式的推断）：在训练所用的因果结构下，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 本身也是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mclose">)</span></span></span></span> 的函数加上采样噪声，并不携带 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mclose">)</span></span></span></span> 之外的新信息。因此从纯信息量看，条件在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 上不可能严格优于条件在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="mopen">(</span><span class="mord mathnormal">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mclose">)</span></span></span></span> 上——积分式的价值只能来自计算侧（把一个困难的条件分布拆成两个更容易学的分布）或归纳偏置侧。Fast-WAM 的实验结果与这一读法一致：去掉积分几乎不掉分，去掉塑造 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.044em;">z</span></span></span></span> 的那项损失才掉分。</p><p>值得注意的另一点是，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">λ</span></span></span></span> 的取值在正文中没有给出，也没有敏感性分析；而全文结论恰恰是「<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">vid</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 这一项很重要」，缺 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">λ</span></span></span></span> 扫描是复现上的明显缺口。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：不生成未来，性能会掉吗？</strong> RoboTwin 2.0（2,500 干净 + 25,000 强随机化演示、50+ 任务、每任务 100 次试验）上，Fast-WAM 91.88/91.78（clean/rand，均值 91.8），Fast-WAM-Joint 90.6，Fast-WAM-IDM 91.3。LIBERO 四套件（每套件 500 演示、共 2000 次试验）上，Fast-WAM 均值 97.6，Joint 98.5，IDM 98.0。答案是：不掉，但也别把它读成「更好」——<strong>在 LIBERO 上两个 imagine-then-execute 变体反而都高于 Fast-WAM</strong>，只是差距落在 0.4–0.9 分。</p><p><strong>问题二：去掉训练期视频损失呢？</strong> RoboTwin 掉到 83.8（−8.0），LIBERO 掉到 93.5（−4.1，Spatial 98.2→89.2、Long 95.2→90.0 最明显）。真机折毛巾任务上更极端：正文明确写去掉视频协同训练后成功率只剩 10%。三个带视频协同训练的变体彼此差 1.2 分以内，去掉它掉 8 分乃至归零——归因方向清楚。</p><p><strong>问题三：不用具身预训练能到什么水平？</strong> Fast-WAM 在 RoboTwin 上 91.8，超过所有无具身预训练的对手（Motus from WAN2.2 77.3、LingBot-VA from WAN2.2 80.6），逼近有预训练的 LingBot-VA（92.2）。LIBERO 上 97.6 超过 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>（96.9）。</p><p><strong>问题四：快多少？</strong> Fast-WAM 190 ms，Fast-WAM-IDM 810 ms，约 4.3 倍。需要注意这个分母是作者自己实现的 IDM 变体，不是任何一篇已发表 WAM 的实测延迟。</p><p>真机部分（Galaxea R1 Lite、60 小时遥操作数据、折毛巾）只有图 4，正文没有给出具体成功率与完成时间数值，本文因此未复述；正文明确写<strong>有预训练的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 在该任务上成功率最高、完成时间最短</strong>，而 Fast-WAM 家族内部是 IDM 成功率最高、Fast-WAM 完成时间最好。</p><p>另外表 1 里 LingBot-VA from WAN2.2 的 Rand. 一栏是「–」，其 Average 却记作 80.6（等于 Clean 值），即该行的均值只由一个数算出，与其他行口径不同。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版。</strong> WAM 的增益被拆成「训练期视频协同训练」与「推理期未来生成」两个因素，并在同一骨干下用四个变体做正交对照。RoboTwin 与 LIBERO 上，去掉推理期生成只差 0.4–0.9 分，去掉训练期视频损失差 4–8 分，真机上差到只剩 10% 成功率。据此作者提出 Fast-WAM：训练带视频损失、推理只把干净首帧过一次视频 DiT，190 ms 出 32 步动作块。无具身预训练即可在 RoboTwin 拿 91.8、LIBERO 拿 97.6。但两个仿真基准都已接近天花板，「等价」这一结论的证据强度受此限制。</p><p><strong>三句话版。</strong> 把 WAM 的视频分支当 auxiliary loss 而非 planner 用，推理期直接删掉。仿真与真机上性能基本持平，延迟降到 190 ms。视频预测的价值主要在训练期塑造表示。</p><p><strong>一句话版。</strong> 世界模型可能只需要在训练时存在。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>「Fast-WAM 与 imagine-then-execute 变体成绩相当」这个零结果，在接近饱和的基准上是可解释的证据。</strong></p><p>全文的核心 claim 是一个 null result，而 null result 的说服力完全取决于测量是否有分辨力。LIBERO 上四个配置分别是 97.6/98.5/98.0/93.5——前三者挤在 1 分以内，而 Object 子集上 Fast-WAM 已经是 100.0，天花板效应明显。RoboTwin 上三者是 91.8/90.6/91.3，同样落在 1.2 分带内，论文没有报告多次运行的标准差，也没有做显著性检验。换句话说，「未来想象不重要」这一判断，在两个仿真基准上等价于「未来想象的效应小于噪声底」，而噪声底本身没有被测量。</p><p>更值得警惕的是，唯一没有饱和、也最接近部署条件的实验——真机长时程折毛巾——恰恰给出了<strong>相反方向的信号</strong>：Fast-WAM-IDM 的成功率是家族内最高的，且有预训练的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 全面领先。如果未来想象真的无用，最难的那个任务上不该是 IDM 领先。作者的处理是把这一点归入「整体性能可比」，但它至少说明结论的适用范围应当限定在「短时程、已见分布、评测接近饱和」的设定内。</p><p>论文为这条假设提供的证据是三个基准上的一致排序；缺的证据是方差估计、显著性检验，以及一个未饱和且长时程的定量对照。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周可做的最小验证，不需要复现 6B 模型：</p><ul><li><strong>数据与骨干</strong>：LIBERO-Long（最未饱和的子集，500 条演示），骨干换成任意开源小视频 DiT（如 Wan2.1-1.3B），action expert 缩到 100M 量级。</li><li><strong>实现</strong>：完全照搬本文的三组 token + 结构化掩码，只训 Fast-WAM 与 Fast-WAM w/o video co-train 两档，外加一档 Fast-WAM-IDM。</li><li><strong>关键改动</strong>：每档跑 5 个随机种子，每个 checkpoint 评 500 次 rollout，报均值与标准差。</li><li><strong>测量</strong>：三档的成功率分布，以及 Fast-WAM 与 IDM 之差相对种子间标准差的比值。</li><li><strong>判据</strong>：若 |Fast-WAM − IDM| 小于 0.5 倍种子标准差，支持「未来想象可省」；若 IDM 稳定高出 1 个标准差以上，则本文结论应限定在饱和基准上。若 w/o co-train 的掉幅小于 2 倍标准差，则「视频损失是主因」这一归因同样需要重估。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者立场，最有力的攻击不是质疑数字，而是给出<strong>替代解释</strong>：去掉视频协同训练后掉 8 分，可能与「世界表示」无关。</p><p>理由是这样的：w/o video co-train 变体保留了 6B 的骨干、保留了 Wan2.2 的预训练权重，却只用一个 32 步动作块的回归损失去训练它。这是一个极端不平衡的优化问题——监督信号的维度比参数量小了七八个数量级，视频损失在这里同时扮演着<strong>正则项</strong>与<strong>保持预训练权重不被破坏的锚</strong>。也就是说，掉的 8 分可能是「大骨干在弱监督下漂移」的代价，而不是「缺少世界表示」的代价。</p><p>判决性实验有两个 arm。第一，把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">vid</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 换成一个与世界建模无关但同样稠密的辅助目标——例如让视频分支去重建<strong>当前帧</strong>（而非预测未来），或者去回归一个冻结 DINOv3 的特征。若这些变体也能补回大部分的 8 分，那「视频预测目标塑造世界表示」的叙事就被削弱成「任何稠密辅助监督都行」。第二，把骨干冻结、只训 action expert，比较有无视频损失的差距；若差距大幅缩小，则 8 分主要来自骨干漂移。</p><p>另一条攻击线是延迟归因。190 ms vs 810 ms 的对比里，IDM 变体要跑 10 步去噪生成 9 帧视频；但真实部署中 imagine-then-execute 系统通常会用蒸馏后的少步视频模型。把 IDM 的视频侧换成 2 步蒸馏版本后重测，「4 倍」的结论很可能显著缩水。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>局限驱动。</strong> 本文证明了「未来在推理期可省」，但它同时也把 WAM 退化成了一个无记忆、无重规划的前馈策略：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="mopen">(</span><span class="mord mathnormal">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mclose">)</span></span></span></span> 只依赖当前帧，一旦执行偏离，模型没有任何机制知道自己偏了。而 imagine-then-execute 至少在原理上提供了一个可被检验的中间产物——生成的未来可以和实际观测比对。</p><p><strong>新 framing。</strong> 与其问「要不要在推理期生成未来」，不如问「未来应该在什么时候被生成」。提议把未来想象从<strong>每步都做</strong>改成<strong>按需触发的自监控信号</strong>：绝大多数时刻按 Fast-WAM 的路径走 190 ms 前馈；只有当某个廉价的一致性指标报警时，才付一次完整的视频去噪，用生成的未来与实际后续观测的偏差来判定「模型是否还理解当前场景」，并据此触发重规划或降速。</p><p><strong>可借鉴的相邻工具。</strong> 一是 selective prediction / conformal prediction 里的弃权机制，用来把「什么时候值得付这次算力」形式化为一个带覆盖率保证的决策问题；二是 model-based RL 中的 model disagreement 信号（多次采样 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.044em;">z</span></span></span></span> 或多头预测的分歧度），它天然可以从 Fast-WAM 现有的 flow matching 采样里免费获得，无需额外结构。</p><p><strong>第一个实验。</strong> 在真机折毛巾任务上记录整段 rollout 的逐步动作分歧度与最终成败，检验分歧度是否能在失败发生前若干步预测失败；若 AUC 明显高于随机，再把它接成触发器，比较「全程 Fast-WAM」「全程 IDM」「按需触发」三档的成功率-平均延迟曲线。若按需触发能以接近 Fast-WAM 的平均延迟拿到接近或超过 IDM 的成功率，就说明未来想象的正确用法是诊断而非规划。</p>',58)])])}const d=a(l,[["render",e]]);export{o as __pageData,d as default};
